<body class="hold-transition no-sidebar">
<div class="wrapper">
<div class="content-wrapper"><section class="content p-3 p-md-4 menu-page">
<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.datatables.net/1.13.8/css/dataTables.bootstrap5.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/toastr.js/latest/toastr.min.css" rel="stylesheet">
<style>
.menu-page{--m-ink:#14233b;--m-muted:#6b7890;--m-line:#e5eaf2;color:var(--m-ink)}.menu-hero{position:relative;overflow:hidden;border-radius:20px;padding:25px;background:linear-gradient(120deg,#10283d,#145d69 65%,#1c8d83);color:#fff;box-shadow:0 16px 34px rgba(16,40,61,.18)}.menu-hero:after{content:"";position:absolute;width:230px;height:230px;right:-55px;top:-95px;border:1px solid rgba(255,255,255,.16);border-radius:50%;box-shadow:0 0 0 28px rgba(255,255,255,.04),0 0 0 58px rgba(255,255,255,.03)}.menu-widget,.menu-panel{background:#fff;border:1px solid var(--m-line);border-radius:16px;box-shadow:0 8px 22px rgba(19,35,59,.045)}.menu-widget{padding:16px 18px;height:100%}.menu-label{font-size:12px;color:var(--m-muted);text-transform:uppercase;letter-spacing:.07em}.menu-value{font-size:25px;font-weight:750}.menu-icon{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:#e8f4f4;color:#176b78}.menu-panel{padding:18px}.menu-form-control{border:1px solid #d7dfeb;border-radius:10px;min-height:40px}.menu-chip{width:36px;height:36px;display:inline-grid;place-items:center;border-radius:11px;background:#edf5f6;color:#176b78}.menu-row-actions{white-space:nowrap}.menu-page table.dataTable thead th{background:#f7f9fc!important;border-bottom:1px solid #e5eaf2!important}.menu-page .dataTables_wrapper .dataTables_processing{background:#fff;border:1px solid #dfe7ef;border-radius:12px;padding:12px;box-shadow:0 8px 25px #14233b18}.menu-preview{background:#f7fafb;border:1px dashed #d1e0e3;border-radius:12px;padding:13px}
@media(max-width:767.98px){.menu-hero{padding:20px}.menu-panel{padding:13px}}
</style>
<style>.no-sidebar .content-wrapper{margin-left:0!important}</style>
<div class="menu-hero mb-3 d-flex flex-column flex-md-row justify-content-between align-items-md-center"><div><div class="small text-uppercase fw-bold mb-1" style="letter-spacing:.12em;opacity:.72">Navigation architecture</div><h2 class="fw-bold mb-1">Master Menu</h2><div style="opacity:.78">Atur struktur navigasi, urutan, ikon, dan status modul KARISMA ERP.</div></div><div class="d-flex flex-wrap gap-2 mt-3 mt-md-0"><a class="btn btn-outline-light fw-bold" href="<?= base_url('portal') ?>"><i class="fas fa-arrow-left me-1"></i> Kembali ke Portal</a><button class="btn btn-light fw-bold" id="btnAdd"><i class="fas fa-plus me-1"></i> Tambah menu</button></div></div>
<div class="row mb-3"><div class="col-md-4 mb-2"><div class="menu-widget d-flex justify-content-between align-items-center"><div><div class="menu-label">Total menu</div><div class="menu-value" id="menuTotal">—</div></div><span class="menu-icon"><i class="fas fa-sitemap"></i></span></div></div><div class="col-md-4 mb-2"><div class="menu-widget d-flex justify-content-between align-items-center"><div><div class="menu-label">Hasil pencarian/filter</div><div class="menu-value" id="menuFiltered">—</div></div><span class="menu-icon" style="background:#eaf1fb;color:#2763a5"><i class="fas fa-filter"></i></span></div></div><div class="col-md-4 mb-2"><div class="menu-widget d-flex justify-content-between align-items-center"><div><div class="menu-label">Aktif pada halaman</div><div class="menu-value text-success" id="menuActivePage">—</div></div><span class="menu-icon" style="background:#e9f7ef;color:#21864a"><i class="fas fa-check-circle"></i></span></div></div></div>
<div class="menu-panel"><div class="d-flex flex-column flex-md-row justify-content-between align-items-md-center mb-3"><div><h5 class="fw-bold mb-1">Struktur menu</h5><div class="small text-muted">Gunakan pencarian untuk menemukan nama atau URL. Filter status membantu meninjau menu aktif.</div></div><select id="menuStatusFilter" class="form-select menu-form-control mt-2 mt-md-0" style="max-width:180px"><option value="">Semua status</option><option value="1">Aktif</option><option value="0">Nonaktif</option></select></div>
<div class="table-responsive"><table class="table table-hover align-middle w-100" id="tableMenu"><thead><tr><th>Menu</th><th>Induk</th><th>URL</th><th>Urutan</th><th>Status</th><th>Aksi</th></tr></thead></table></div></div>
</section></div></div>
<div class="modal fade" id="modalForm" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-scrollable"><form class="modal-content" id="formData" autocomplete="off"><div class="modal-header"><div><h5 class="modal-title fw-bold">Tambah menu</h5><div class="small text-muted">Lengkapi identitas dan posisi menu.</div></div><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Tutup"></button></div><div class="modal-body"><input type="hidden" id="id_menu"><div class="row g-3"><div class="col-md-6"><label class="form-label fw-semibold" for="parent_id">Menu induk</label><select class="form-select menu-form-control" name="parent_id" id="parent_id"><option value="0">Menu utama (root)</option><?php foreach ($parents as $parent): ?><option value="<?= html_escape($parent['id_menu']) ?>"><?= html_escape($parent['nama_menu']) ?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label fw-semibold" for="nama_menu">Nama menu</label><input class="form-control menu-form-control" name="nama_menu" id="nama_menu" required maxlength="100" placeholder="Contoh: Manajemen User"></div><div class="col-md-6"><label class="form-label fw-semibold" for="icon">Kelas ikon Font Awesome</label><input class="form-control menu-form-control" name="icon" id="icon" placeholder="fas fa-users"><div class="menu-preview mt-2"><span class="menu-chip me-2"><i id="menuIconPreview" class="fas fa-circle"></i></span><span class="small text-muted">Pratinjau ikon</span></div></div><div class="col-md-6"><label class="form-label fw-semibold" for="url">URL / route</label><input class="form-control menu-form-control" name="url" id="url" placeholder="master/user-management"><div class="small text-muted mt-1" id="menuUrlPreview">URL menu akan terlihat di sini.</div></div><div class="col-md-6"><label class="form-label fw-semibold" for="urutan">Urutan tampil</label><input type="number" class="form-control menu-form-control" name="urutan" id="urutan" value="0"></div><div class="col-md-6"><label class="form-label fw-semibold" for="status">Status</label><select class="form-select menu-form-control" name="status" id="status"><option value="1">Aktif</option><option value="0">Nonaktif</option></select></div></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary" id="menuSave" type="submit"><i class="fas fa-save me-1"></i>Simpan menu</button></div></form></div></div>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="https://cdn.datatables.net/1.13.8/js/jquery.dataTables.min.js"></script><script src="https://cdn.datatables.net/1.13.8/js/dataTables.bootstrap5.min.js"></script><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/toastr.js/latest/toastr.min.js"></script>
<script>
$(function(){
    const modal=new bootstrap.Modal(document.getElementById('modalForm'));
    const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
    const parents=<?= json_encode(array_column($parents, 'nama_menu', 'id_menu'), JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_AMP) ?>;
    const table=$('#tableMenu').DataTable({processing:true,serverSide:true,responsive:true,searchDelay:300,ajax:{url:'<?= base_url('master/menu/list') ?>',type:'POST',data:d=>{d.status=$('#menuStatusFilter').val();},dataSrc:function(json){$('#menuTotal').text(json.recordsTotal??0);$('#menuFiltered').text(json.recordsFiltered??0);$('#menuActivePage').text((json.data||[]).filter(row=>parseInt(row.status)===1).length);return json.data||[];}},columns:[
        {data:null,render:r=>`<div class="d-flex align-items-center gap-2"><span class="menu-chip"><i class="${escapeHtml(r.icon||'fas fa-circle')}"></i></span><div><div class="fw-semibold">${escapeHtml(r.nama_menu||'-')}</div><small class="text-muted">ID ${escapeHtml(r.id_menu)}</small></div></div>`},
        {data:'parent_id',render:v=>parseInt(v)===0?'<span class="badge bg-light text-dark">Menu utama</span>':escapeHtml(parents[v]||('Induk #'+v))},
        {data:'url',render:v=>`<code>${escapeHtml(v||'#')}</code>`},{data:'urutan',render:v=>`<span class="badge bg-light text-dark">${escapeHtml(v??0)}</span>`},{data:'status',render:v=>parseInt(v)===1?'<span class="badge bg-success-subtle text-success">Aktif</span>':'<span class="badge bg-secondary-subtle text-secondary">Nonaktif</span>'},
        {data:null,orderable:false,searchable:false,render:r=>`<div class="menu-row-actions"><button class="btn btn-sm btn-outline-primary btn-edit" data-id="${escapeHtml(r.id_menu)}" title="Ubah menu"><i class="fas fa-pen"></i></button> <button class="btn btn-sm btn-outline-danger btn-delete" data-id="${escapeHtml(r.id_menu)}" title="Hapus menu"><i class="fas fa-trash"></i></button></div>`}
    ],language:{emptyTable:'Belum ada menu.',processing:'<i class="fas fa-circle-notch fa-spin me-2"></i>Memuat menu…',search:'Cari:',lengthMenu:'Tampilkan _MENU_',info:'Menampilkan _START_–_END_ dari _TOTAL_ menu',infoEmpty:'Belum ada menu',zeroRecords:'Menu tidak ditemukan',paginate:{previous:'‹',next:'›'}}});
    function resetForm(){const form=$('#formData')[0];form.reset();$('#id_menu').val('');$('#parent_id').val('0');$('#urutan').val(0);$('.modal-title').text('Tambah menu');updatePreview();}
    function updatePreview(){const icon=$('#icon').val().trim()||'fas fa-circle';$('#menuIconPreview').attr('class',icon);$('#menuUrlPreview').text($('#url').val().trim()||'URL menu akan terlihat di sini.');}
    $('#btnAdd').on('click',function(){resetForm();modal.show();});$('#menuStatusFilter').on('change',()=>table.ajax.reload());$('#icon,#url').on('input',updatePreview);
    $('#tableMenu').on('click','.btn-edit',function(){const id=$(this).data('id');$.getJSON('<?= base_url('master/menu/detail/') ?>'+encodeURIComponent(id)).done(function(res){if(!res.status){toastr.error(res.message);return;}resetForm();$.each(res.data,(key,value)=>$('#'+key).val(value));$('.modal-title').text('Ubah menu');updatePreview();modal.show();}).fail(()=>toastr.error('Data menu gagal dimuat.'));});
    $('#formData').on('submit',function(event){event.preventDefault();const id=$('#id_menu').val(),$button=$('#menuSave'),old=$button.html();$button.prop('disabled',true).html('<i class="fas fa-circle-notch fa-spin me-1"></i>Menyimpan');$.ajax({url:id?'<?= base_url('master/menu/update/') ?>'+encodeURIComponent(id):'<?= base_url('master/menu/save') ?>',type:'POST',data:$(this).serialize(),dataType:'json'}).done(function(res){if(!res.status){toastr.error(res.message);return;}toastr.success(res.message);modal.hide();table.ajax.reload(null,false);}).fail(()=>toastr.error('Server tidak merespons saat menyimpan menu.')).always(()=>$button.prop('disabled',false).html(old));});
    $('#tableMenu').on('click','.btn-delete',function(){const id=$(this).data('id');Swal.fire({title:'Hapus menu ini?',text:'Menu yang masih digunakan oleh hak akses dapat berdampak pada navigasi pengguna.',icon:'warning',showCancelButton:true,confirmButtonText:'Hapus menu',cancelButtonText:'Batal'}).then(result=>{if(!result.isConfirmed)return;$.post('<?= base_url('master/menu/delete/') ?>'+encodeURIComponent(id),{},function(res){if(res.status){toastr.success(res.message);table.ajax.reload(null,false);}else toastr.error(res.message);},'json').fail(()=>toastr.error('Menu gagal dihapus.'));});});
});
</script></body>
